style.css:
@-moz-document domain("www.linetv.tw") {
/* Hide Ads */
  .fixed.z-\[999\],
  .text-linetv-header-yellow,
  .btn--secondary,
  .md\:w-1\/3 .lazyload-wrapper > section,
  [class^="SmartChannelTemplatesstyled"] {
    display: none !important;  
  }

  /* Hide logo */
  .sponsor-logo-class {
    display: none !important;
  }

  /* Subtitle text shadow */
  .vjs-linetv.vjs-fullscreen .vjs-text-track-display .vjs-text-track-cue > div,
  .vjs-linetv .vjs-text-track-display .vjs-text-track-cue > div {
    background-color: transparent !important;
    scale: 125%;
    text-shadow: 
      #000 -1px -1px 10px, 
      #000 1px -1px 10px, 
      #000 -1px 1px 10px, 
      #000 1px 1px 10px !important;
  }
}
